styles.h1:
font-family: "Helvetica Neue", "PingFang SC", sans-serif;
font-size: 28px;
position: relative;
color: #000;
margin: 0 0 30px 0;
letter-spacing: -0.5px;
font-weight: 700;
text-align: left;
line-height: 1.2;

styles.h2:
font-size: 18px;
color: #000;
margin: 30px 0 20px 0;
font-weight: 600;
letter-spacing: -0.3px;
text-align: left;
position: relative;
padding-bottom: 8px;
border-bottom: 1px solid #eee;

styles.h3:
display: block;
color: #000;
margin: 24px 0 8px 0;
font-size: 16px;
font-weight: 600;

styles.h6:
color: #6b8c42;
margin-top: 1.2em;
margin-bottom: 0.5em;
font-weight: 700;
border-bottom: 1px solid #d4d9c9;
padding-bottom: 0.3em;

styles.a:
color: #000;
text-decoration: none;
border-bottom: 1px solid #000;
transition: all 0.2s ease;

styles.ol:
background: white;
border-radius: 12px;
padding: 20px 25px;
box-shadow: 0 4px 15px rgba(0, 0, 0, 0.03);

styles.li:
position: relative;


margin-bottom: 12px;
color: #333;
line-height: 1.6;
font-size: 16px;

styles.blockquote:
background-color: #fff;
border-left: 2px solid #000;
color: #555;
padding: 15px 20px;
margin: 20px 0;
font-style: italic;

styles.pre:
border: 1px solid #eee;
background-color: #f9f9f9;
padding: 15px;
overflow-x: auto;
font-family: "SF Mono", monospace;
font-size: 14px;

styles.img:
max-width: 100%;
height: auto;
margin: 25px 0;
border: none;

styles.table:
border-collapse: collapse;
margin: 25px 0;
width: 100%;
border-top: 1px solid #000;
border-bottom: 1px solid #000;

styles.th:
background-color: #fff;
color: #000;
background: rgba(0, 0, 0, 0.05);
padding: 12px 8px;
text-align: left;
font-weight: 600;
border-bottom: 1px solid #000;
